utton[aria-pressed=true]{color:var(--text-color);background:var(--primary-soft-bg);border-color:var(--primary-soft-border)}.daily-categories i{width:6px;height:6px;border-radius:50%;background:var(--category)}.daily-categories small{font-size:10px;opacity:.7}.daily-context{border-top:1px solid var(--row-border);padding-top:14px;display:flex;gap:12px;align-items:start;justify-content:space-between;color:var(--muted-color);font-size:10px}.daily-context p{line-height:1.8}.daily-fresh-dot{display:inline-block;width:5px;height:5px;border-radius:50%;background:#4ba582;margin-right:6px}.daily-context details{text-align:right}.daily-context summary{cursor:pointer;white-space:nowrap}.daily-filter-chips{display:flex;gap:6px;flex-wrap:wrap;justify-content:flex-end;margin-top:10px;max-width:430px}.daily-filter-chips span{overflow-wrap:anywhere;max-width:100%;padding:4px 8px;border-radius:5px;background:var(--tag-bg);color:var(--tag-color);font-size:10px}.daily-filter-chips .is-excluded{text-decoration:line-through;opacity:.7}.daily-results-header{display:flex;justify-content:space-between;align-items:center;gap:12px;padding:2px 4px;font-size:12px;color:var(--muted-color)}.daily-results-header strong{color:var(--text-color);font-weight:600;padding:0 4px}.daily-results-header button,.daily-error button{border:0;background:none;padding:6px;color:var(--primary-color);font-size:11px;cursor:pointer}.daily-error{display:flex;align-items:center;justify-content:space-between;padding:12px;border:1px solid var(--row-border);border-radius:8px;color:var(--text-color);font-size:12px}.daily-group-pill:focus-visible,.daily-categories button:focus-visible{outline:2px solid var(--primary-color);outline-offset:1px}@media(max-width:600px){.daily-page{padding:12px}.daily-header-card{padding:18px 16px;gap:12px;border-radius:12px}.daily-heading h1{font-size:22px;margin:3px 0}.daily-eyebrow{display:none}.daily-total{font-size:26px}.daily-heading p{display:none}.daily-group-pill{flex:0 0 auto;min-width:110px}.daily-context{flex-wrap:wrap;align-items:center;gap:8px}.daily-context p{flex:1;min-width:195px;font-size:9px}.daily-context details{text-align:left}.daily-context details[open]{flex-basis:100%}.daily-filter-chips{justify-content:flex-start}.daily-categories{gap:6px}.daily-categories button{min-height:36px}}
</style>
